class Solution
{
    int dfs(TreeNode* node, vector<vector<int>>& groups)
    {
        if (!node) return -1;
        int level = 1 + max(dfs(node->left, groups),
                            dfs(node->right, groups));
        if (level == (int)groups.size()) groups.push_back({});
        groups[level].push_back(node->val);
        return level;
    }
public:
    vector<vector<int>> findLeaves(TreeNode* root) {
        vector<vector<int>> groups;
        dfs(root, groups);
        return groups;
    }
};
